import React, { useState } from 'react';
import TokenPriceChecker from './TokenPriceChecker';
import MarketCapTool from './MarketCapTool';
import PumpFunLauncher from './PumpFunLauncher';
import './App.css';

function App() {
  const [activeTab, setActiveTab] = useState('price'); // 'price', 'marketcap', 或 'pumpfun'

  return (
    <div className="App">
      <nav className="app-nav">
        <h1>Solana DeFi 工具</h1>
        <div className="nav-tabs">
          <button 
            className={`nav-tab ${activeTab === 'price' ? 'active' : ''}`}
            onClick={() => setActiveTab('price')}
          >
            📊 价格查询
          </button>
          <button 
            className={`nav-tab ${activeTab === 'marketcap' ? 'active' : ''}`}
            onClick={() => setActiveTab('marketcap')}
          >
            ⚡ 批量交易
          </button>
          <button 
            className={`nav-tab ${activeTab === 'pumpfun' ? 'active' : ''}`}
            onClick={() => setActiveTab('pumpfun')}
          >
            🚀 代币发行
          </button>
        </div>
      </nav>

      <main className="app-main">
        {activeTab === 'price' && <TokenPriceChecker />}
        {activeTab === 'marketcap' && <MarketCapTool />}
        {activeTab === 'pumpfun' && <PumpFunLauncher />}
      </main>
    </div>
  );
}

export default App;
