import React, { useState } from 'react';
import axios from 'axios';
import './TokenPriceChecker.css';

const TokenPriceChecker = () => {
  const [tokenAddress, setTokenAddress] = useState('');
  const [tokenData, setTokenData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // API endpoints
  const JUPITER_PRICE_API = 'https://lite-api.jup.ag/price/v2';
  const JUPITER_TOKEN_API = 'https://lite-api.jup.ag/tokens/v1/all';
  const DEXSCREENER_API = 'https://api.dexscreener.com/latest/dex/tokens';
  
  // LetsBonk API endpoints (通过DexScreener和Jupiter聚合数据)
  const BONK_POOLS_API = 'https://api.dexscreener.com/latest/dex/search';
  const JUPITER_POOLS_API = 'https://api.jup.ag/pools';

  // 获取代币基本信息
  const getTokenInfo = async (address) => {
    try {
      // 尝试使用单个代币查询端点
      console.log('正在查询代币信息:', address);
      const response = await axios.get(`https://lite-api.jup.ag/tokens/v1/token/${address}`, {
        timeout: 8000,
        headers: {
          'Accept': 'application/json',
        }
      });
      
      console.log('代币信息响应:', response.data);
      return response.data;
    } catch (error) {
      console.log('单个代币查询失败，尝试其他方法:', error.message);
      
            // 如果单个查询失败，尝试使用DexScreener API作为备选
      try {
        console.log('尝试从DexScreener获取代币信息');
        const dexResponse = await axios.get(`https://api.dexscreener.com/latest/dex/tokens/${address}`, {
          timeout: 8000
        });
        
        if (dexResponse.data && dexResponse.data.pairs && dexResponse.data.pairs.length > 0) {
          const tokenData = dexResponse.data.pairs[0].baseToken;
          console.log('DexScreener代币信息:', tokenData);
          return {
            address: address,
            name: tokenData.name || 'Unknown Token',
            symbol: tokenData.symbol || 'Unknown',
            decimals: tokenData.decimals || 'Unknown',
            source: 'dexscreener'
          };
        }
      } catch (dexError) {
        console.log('DexScreener查询也失败:', dexError.message);
      }
      
      // 尝试从CoinGecko获取信息（作为第三个备选）
      try {
        console.log('尝试从其他数据源获取代币信息');
        const geckoResponse = await axios.get(`https://api.coingecko.com/api/v3/coins/solana/contract/${address}`, {
          timeout: 8000
        });
        
        if (geckoResponse.data) {
          return {
            address: address,
            name: geckoResponse.data.name || 'Unknown Token',
            symbol: geckoResponse.data.symbol?.toUpperCase() || 'Unknown',
            decimals: geckoResponse.data.detail_platforms?.solana?.decimal_place || 'Unknown',
            source: 'coingecko'
          };
        }
      } catch (geckoError) {
        console.log('CoinGecko查询也失败:', geckoError.message);
      }
      
      // 最后的备选方案：返回基本信息
      return {
        address: address,
        name: 'Unknown Token',
        symbol: 'Unknown',
        decimals: 'Unknown',
        note: 'Unable to fetch token metadata'
      };
    }
  };

  // 获取代币价格
  const getTokenPrice = async (address) => {
    try {
      console.log('正在查询代币价格:', address);
      const response = await axios.get(`${JUPITER_PRICE_API}?ids=${address}&showExtraInfo=true`, {
        timeout: 10000, // 10秒超时
        headers: {
          'Accept': 'application/json',
        }
      });
      
      console.log('Jupiter API响应:', response.data);
      
      if (response.data && response.data.data && response.data.data[address]) {
        const priceData = response.data.data[address];
        return {
          price: parseFloat(priceData.price),
          extraInfo: priceData.extraInfo,
          source: 'jupiter'
        };
      } else {
        console.log('未找到该代币的价格数据');
        return null;
      }
    } catch (error) {
      console.error('获取代币价格失败:', error);
      if (error.response) {
        console.error('响应状态:', error.response.status);
        console.error('响应数据:', error.response.data);
      }
      return null;
    }
  };

  // 获取多个DEX的池子信息
  const getDexPoolsInfo = async (address) => {
    try {
      console.log('从DexScreener获取多平台池子信息');
      const response = await axios.get(`${DEXSCREENER_API}/${address}`, {
        timeout: 10000,
        headers: {
          'Accept': 'application/json',
        }
      });
      
      if (response.data && response.data.pairs) {
        const pools = response.data.pairs;
        const poolsByDex = {};
        
        pools.forEach(pool => {
          const dexName = pool.dexId.toLowerCase();
          if (!poolsByDex[dexName]) {
            poolsByDex[dexName] = [];
          }
          
          poolsByDex[dexName].push({
            address: pool.pairAddress,
            baseToken: pool.baseToken,
            quoteToken: pool.quoteToken,
            price: parseFloat(pool.priceUsd || 0),
            priceNative: parseFloat(pool.priceNative || 0),
            liquidity: parseFloat(pool.liquidity?.usd || 0),
            volume24h: parseFloat(pool.volume?.h24 || 0),
            volume1h: parseFloat(pool.volume?.h1 || 0),
            priceChange24h: parseFloat(pool.priceChange?.h24 || 0),
            priceChange1h: parseFloat(pool.priceChange?.h1 || 0),
            marketCap: parseFloat(pool.fdv || 0),
            poolCreated: pool.pairCreatedAt,
            url: pool.url,
            dexName: pool.dexId,
            chainId: pool.chainId
          });
        });
        
        return poolsByDex;
      }
      
      return {};
    } catch (error) {
      console.error('获取DEX池子信息失败:', error);
      return {};
    }
  };

  // 获取Jupiter的详细池子信息
  const getJupiterPoolsInfo = async (address) => {
    try {
      console.log('从Jupiter获取详细池子信息');
      const response = await axios.get(`${JUPITER_PRICE_API}?ids=${address}&showExtraInfo=true`, {
        timeout: 10000,
        headers: {
          'Accept': 'application/json',
        }
      });
      
      if (response.data && response.data.data && response.data.data[address]) {
        const priceData = response.data.data[address];
        const extraInfo = priceData.extraInfo;
        
        return {
          price: parseFloat(priceData.price),
          buyPrice: extraInfo?.quotedPrice?.buyPrice ? parseFloat(extraInfo.quotedPrice.buyPrice) : parseFloat(priceData.price),
          sellPrice: extraInfo?.quotedPrice?.sellPrice ? parseFloat(extraInfo.quotedPrice.sellPrice) : parseFloat(priceData.price),
          lastSwapPrice: extraInfo?.lastSwappedPrice ? {
            buyPrice: parseFloat(extraInfo.lastSwappedPrice.lastJupiterBuyPrice || 0),
            sellPrice: parseFloat(extraInfo.lastSwappedPrice.lastJupiterSellPrice || 0)
          } : null,
          confidence: extraInfo?.confidenceLevel || 'unknown',
          source: 'jupiter',
          aggregatedFromDEXs: ['Raydium', 'Orca', 'Pump.fun', 'Meteora', 'Whirlpool'],
          note: 'Jupiter聚合多个DEX的最优价格'
        };
      }
      
      return null;
    } catch (error) {
      console.error('获取Jupiter池子信息失败:', error);
      return null;
    }
  };

  // 专门查询LetsBonk相关的池子
  const getLetsBonkInfo = async (address) => {
    try {
      console.log('查询LetsBonk相关池子信息');
      
      // 通过DexScreener搜索包含bonk或相关关键词的池子
      const searchResponse = await axios.get(`${BONK_POOLS_API}?q=${address}`, {
        timeout: 10000,
        headers: {
          'Accept': 'application/json',
        }
      });
      
      if (searchResponse.data && searchResponse.data.pairs) {
        // 过滤出可能与LetsBonk相关的池子
        const bonkRelatedPools = searchResponse.data.pairs.filter(pool => {
          const dexName = pool.dexId.toLowerCase();
          const poolInfo = pool.info || '';
          
          // 查找包含bonk相关关键词或特定DEX的池子
          return (
            dexName.includes('bonk') ||
            poolInfo.toLowerCase().includes('bonk') ||
            pool.baseToken.symbol.toLowerCase().includes('bonk') ||
            pool.quoteToken.symbol.toLowerCase().includes('bonk') ||
            // 也包括一些可能与LetsBonk平台相关的DEX
            dexName.includes('jupiter') ||
            dexName.includes('raydium')
          );
        });
        
        if (bonkRelatedPools.length > 0) {
          return bonkRelatedPools.map(pool => ({
            address: pool.pairAddress,
            baseToken: pool.baseToken,
            quoteToken: pool.quoteToken,
            price: parseFloat(pool.priceUsd || 0),
            liquidity: parseFloat(pool.liquidity?.usd || 0),
            volume24h: parseFloat(pool.volume?.h24 || 0),
            priceChange24h: parseFloat(pool.priceChange?.h24 || 0),
            dexName: pool.dexId,
            url: pool.url,
            source: 'letsbonk-related'
          }));
        }
      }
      
      return null;
    } catch (error) {
      console.error('获取LetsBonk信息失败:', error);
      return null;
    }
  };

  const handleSearch = async () => {
    if (!tokenAddress.trim()) {
      setError('请输入代币地址');
      return;
    }

    setLoading(true);
    setError('');
    setTokenData(null);

    try {
      // 验证Solana地址格式
      if (tokenAddress.length < 32 || tokenAddress.length > 44) {
        throw new Error('无效的Solana地址格式');
      }

      // 并行获取多个平台的数据
      const [tokenInfo, priceData, jupiterPools, dexPools, bonkInfo] = await Promise.all([
        getTokenInfo(tokenAddress),
        getTokenPrice(tokenAddress),
        getJupiterPoolsInfo(tokenAddress),
        getDexPoolsInfo(tokenAddress),
        getLetsBonkInfo(tokenAddress)
      ]);

      const result = {
        address: tokenAddress,
        info: tokenInfo,
        jupiterPrice: priceData,
        jupiterPools: jupiterPools,
        dexPools: dexPools,
        letsBonkInfo: bonkInfo,
        timestamp: new Date().toLocaleString()
      };

      if (!priceData && !jupiterPools && Object.keys(dexPools).length === 0) {
        setError('未找到该代币的价格数据。可能原因：1) 代币地址无效 2) 代币未在交易所交易 3) API暂时不可用');
      } else {
        setTokenData(result);
      }
    } catch (err) {
      console.error('查询过程出错:', err);
      setError(`查询失败: ${err.message || '未知错误'}。请检查网络连接和代币地址。`);
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e) => {
    setTokenAddress(e.target.value);
    setError('');
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  return (
    <div className="token-price-checker">
      <div className="search-container">
        <h2>🔍 多平台代币价格查询工具</h2>
        <div className="feature-highlight">
          <p>✨ <strong>全新功能</strong>：同时查询多个平台的池子信息</p>
          <ul>
            <li>🚀 <strong>Jupiter</strong> - 聚合多个DEX的最优价格</li>
            <li>🌊 <strong>Raydium</strong> - 主流AMM池子信息</li>
            <li>🐋 <strong>Orca</strong> - 高效稳定的交易池</li>
            <li>🎯 <strong>LetsBonk</strong> - 发现Bonk相关的特色池子</li>
            <li>🚀 <strong>Pump.fun</strong> - 新币发行平台</li>
            <li>☄️ <strong>Meteora</strong> - 动态流动性池</li>
          </ul>
        </div>
        <div className="input-group">
          <input
            type="text"
            value={tokenAddress}
            onChange={handleInputChange}
            onKeyPress={handleKeyPress}
            placeholder="请输入Solana代币地址..."
            className="token-input"
            disabled={loading}
          />
          <button 
            onClick={handleSearch}
            disabled={loading || !tokenAddress.trim()}
            className="search-button"
          >
            {loading ? '查询中...' : '查询'}
          </button>
        </div>
        
        <div className="quick-test-buttons">
          <p>快速测试：</p>
          <button 
            className="test-button" 
            onClick={() => setTokenAddress('So11111111111111111111111111111111111111112')}
            disabled={loading}
          >
            SOL
          </button>
          <button 
            className="test-button" 
            onClick={() => setTokenAddress('JUPyiwrYJFskUPiHa7hkeR8VUtAeFoSYbKedZNsDvCN')}
            disabled={loading}
          >
            JUP
          </button>
          <button 
            className="test-button" 
            onClick={() => setTokenAddress('EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v')}
            disabled={loading}
          >
            USDC
          </button>
          <button 
            className="test-button" 
            onClick={() => setTokenAddress('DezXAZ8z7PnrnRJjz3wXBoRgixCa6xjnB7YaB1pPB263')}
            disabled={loading}
          >
            BONK
          </button>
          <button 
            className="test-button" 
            onClick={() => setTokenAddress('7vfCXTUXx5WJV5JADk17DUJ4ksgau7utNKj4b963voxs')}
            disabled={loading}
          >
            ORCA
          </button>
          <button 
            className="test-button" 
            onClick={() => setTokenAddress('4k3Dyjzvzp8eMZWUXbBCjEvwSkkk59S5iCNLY3QrkX6R')}
            disabled={loading}
          >
            RAY
          </button>
        </div>
        {error && <div className="error-message">{error}</div>}
      </div>

      {tokenData && (
        <div className="results-container">
          <div className="token-header">
            <h3>代币信息</h3>
            <div className="update-time">更新时间: {tokenData.timestamp}</div>
          </div>
          
          <div className="token-basic-info">
            <div className="info-item">
              <label>代币地址:</label>
              <span className="address">{tokenData.address}</span>
            </div>
            
            {tokenData.info && (
              <>
                <div className="info-item">
                  <label>代币名称:</label>
                  <span>{tokenData.info.name || 'Unknown'}</span>
                </div>
                <div className="info-item">
                  <label>代币符号:</label>
                  <span>{tokenData.info.symbol || 'Unknown'}</span>
                </div>
                                 <div className="info-item">
                   <label>小数位数:</label>
                   <span>{tokenData.info.decimals || 'Unknown'}</span>
                 </div>
                 {tokenData.info.source && (
                   <div className="info-item">
                     <label>信息来源:</label>
                     <span className="source-info">{tokenData.info.source}</span>
                   </div>
                 )}
              </>
            )}
          </div>

          <div className="pools-comparison">
            {/* Jupiter 聚合价格 */}
            <div className="price-section">
              <h4>🚀 Jupiter 聚合价格</h4>
              {tokenData.jupiterPools ? (
                <div className="price-details">
                  <div className="price-item">
                    <label>当前价格:</label>
                    <span className="price">${tokenData.jupiterPools.price?.toFixed(8) || 'N/A'}</span>
                  </div>
                  <div className="price-item">
                    <label>买入价格:</label>
                    <span className="price">${tokenData.jupiterPools.buyPrice?.toFixed(8) || 'N/A'}</span>
                  </div>
                  <div className="price-item">
                    <label>卖出价格:</label>
                    <span className="price">${tokenData.jupiterPools.sellPrice?.toFixed(8) || 'N/A'}</span>
                  </div>
                  <div className="price-item">
                    <label>信心水平:</label>
                    <span className={`confidence ${tokenData.jupiterPools.confidence}`}>
                      {tokenData.jupiterPools.confidence}
                    </span>
                  </div>
                  <div className="price-item">
                    <label>聚合DEX:</label>
                    <span className="dex-list">
                      {tokenData.jupiterPools.aggregatedFromDEXs?.join(', ') || 'N/A'}
                    </span>
                  </div>
                  {tokenData.jupiterPools.lastSwapPrice && (
                    <>
                      <div className="price-item">
                        <label>最近买入:</label>
                        <span className="price">${tokenData.jupiterPools.lastSwapPrice.buyPrice?.toFixed(8) || 'N/A'}</span>
                      </div>
                      <div className="price-item">
                        <label>最近卖出:</label>
                        <span className="price">${tokenData.jupiterPools.lastSwapPrice.sellPrice?.toFixed(8) || 'N/A'}</span>
                      </div>
                    </>
                  )}
                </div>
              ) : (
                <div className="no-data">暂无Jupiter价格数据</div>
              )}
            </div>

            {/* DEX 池子信息 */}
            {Object.keys(tokenData.dexPools).length > 0 && (
              <div className="dex-pools-section">
                <h4>🏊‍♂️ DEX 池子信息</h4>
                {Object.entries(tokenData.dexPools).map(([dexName, pools]) => (
                  <div key={dexName} className="dex-pool-group">
                    <div className="dex-header">
                      <h5>
                        {dexName.includes('pump') ? '🚀 Pump.fun' : 
                         dexName.includes('raydium') ? '🌊 Raydium' :
                         dexName.includes('orca') ? '🐋 Orca' :
                         dexName.includes('jupiter') ? '🪐 Jupiter' :
                         dexName.includes('meteora') ? '☄️ Meteora' : 
                         `📊 ${dexName.toUpperCase()}`}
                      </h5>
                      <span className="pool-count">{pools.length} 个池子</span>
                    </div>
                    {pools.slice(0, 3).map((pool, index) => (
                      <div key={index} className="pool-item">
                        <div className="pool-header">
                          <span className="pool-pair">
                            {pool.baseToken.symbol}/{pool.quoteToken.symbol}
                          </span>
                          <span className="pool-price">${pool.price?.toFixed(8) || 'N/A'}</span>
                        </div>
                        <div className="pool-details">
                          <div className="pool-stat">
                            <label>流动性:</label>
                            <span>${pool.liquidity?.toLocaleString() || 'N/A'}</span>
                          </div>
                          <div className="pool-stat">
                            <label>24h交易量:</label>
                            <span>${pool.volume24h?.toLocaleString() || 'N/A'}</span>
                          </div>
                          <div className="pool-stat">
                            <label>24h涨跌:</label>
                            <span className={`change ${pool.priceChange24h >= 0 ? 'positive' : 'negative'}`}>
                              {pool.priceChange24h?.toFixed(2) || 0}%
                            </span>
                          </div>
                          {pool.url && (
                            <div className="pool-stat">
                              <a href={pool.url} target="_blank" rel="noopener noreferrer" className="pool-link">
                                查看详情 →
                              </a>
                            </div>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                ))}
              </div>
            )}

            {/* LetsBonk 相关信息 */}
            {tokenData.letsBonkInfo && tokenData.letsBonkInfo.length > 0 && (
              <div className="letsbonk-section">
                <h4>🎯 LetsBonk 相关池子</h4>
                {tokenData.letsBonkInfo.slice(0, 3).map((pool, index) => (
                  <div key={index} className="bonk-pool-item">
                    <div className="pool-header">
                      <span className="pool-pair">
                        {pool.baseToken.symbol}/{pool.quoteToken.symbol}
                      </span>
                      <span className="pool-price">${pool.price?.toFixed(8) || 'N/A'}</span>
                    </div>
                    <div className="pool-details">
                      <div className="pool-stat">
                        <label>DEX:</label>
                        <span>{pool.dexName}</span>
                      </div>
                      <div className="pool-stat">
                        <label>流动性:</label>
                        <span>${pool.liquidity?.toLocaleString() || 'N/A'}</span>
                      </div>
                      <div className="pool-stat">
                        <label>24h交易量:</label>
                        <span>${pool.volume24h?.toLocaleString() || 'N/A'}</span>
                      </div>
                      <div className="pool-stat">
                        <label>24h涨跌:</label>
                        <span className={`change ${pool.priceChange24h >= 0 ? 'positive' : 'negative'}`}>
                          {pool.priceChange24h?.toFixed(2) || 0}%
                        </span>
                      </div>
                      {pool.url && (
                        <div className="pool-stat">
                          <a href={pool.url} target="_blank" rel="noopener noreferrer" className="pool-link">
                            查看详情 →
                          </a>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

            {/* 价格比较汇总 */}
            {tokenData.jupiterPools && (
              <div className="price-comparison-summary">
                <h4>💰 交易分析</h4>
                <div className="spread-info">
                  {(() => {
                    const buyPrice = tokenData.jupiterPools?.buyPrice || 0;
                    const sellPrice = tokenData.jupiterPools?.sellPrice || 0;
                    const spread = buyPrice > 0 && sellPrice > 0 ? ((buyPrice - sellPrice) / sellPrice * 100).toFixed(2) : 0;
                    const isWideSpread = Math.abs(spread) > 2;
                    
                    // 计算最高和最低价格
                    const allPrices = [];
                    if (tokenData.jupiterPools?.price) allPrices.push(tokenData.jupiterPools.price);
                    
                    Object.values(tokenData.dexPools).forEach(pools => {
                      pools.forEach(pool => {
                        if (pool.price) allPrices.push(pool.price);
                      });
                    });
                    
                    const maxPrice = Math.max(...allPrices);
                    const minPrice = Math.min(...allPrices);
                    const priceDiff = maxPrice > 0 && minPrice > 0 ? ((maxPrice - minPrice) / minPrice * 100).toFixed(2) : 0;
                    
                    return (
                      <>
                        <div className="spread-item">
                          <label>Jupiter买卖价差:</label>
                          <span className={`spread ${spread > 0 ? 'positive' : 'negative'}`}>
                            {spread}%
                          </span>
                        </div>
                        <div className="spread-item">
                          <label>流动性状态:</label>
                          <span className={`liquidity ${isWideSpread ? 'low' : 'good'}`}>
                            {isWideSpread ? '流动性较低' : '流动性良好'}
                          </span>
                        </div>
                        {allPrices.length > 1 && (
                          <>
                            <div className="spread-item">
                              <label>跨DEX价差:</label>
                              <span className={`spread ${priceDiff > 3 ? 'high' : 'normal'}`}>
                                {priceDiff}%
                              </span>
                            </div>
                            <div className="spread-item">
                              <label>最高价:</label>
                              <span className="price">${maxPrice.toFixed(8)}</span>
                            </div>
                            <div className="spread-item">
                              <label>最低价:</label>
                              <span className="price">${minPrice.toFixed(8)}</span>
                            </div>
                          </>
                        )}
                        {isWideSpread && (
                          <div className="arbitrage-alert">
                            ⚠️ 价差较大，交易时请注意滑点
                          </div>
                        )}
                        {parseFloat(priceDiff) > 5 && (
                          <div className="arbitrage-alert">
                            🔥 跨DEX套利机会！不同平台价差超过5%
                          </div>
                        )}
                      </>
                    );
                  })()}
                </div>
              </div>
            )}
            
            {/* 池子统计 */}
            {Object.keys(tokenData.dexPools).length > 0 && (
              <div className="pools-stats">
                <h4>📊 池子统计</h4>
                <div className="stats-grid">
                  <div className="stat-item">
                    <label>DEX平台数:</label>
                    <span>{Object.keys(tokenData.dexPools).length}</span>
                  </div>
                  <div className="stat-item">
                    <label>总池子数:</label>
                    <span>{Object.values(tokenData.dexPools).reduce((total, pools) => total + pools.length, 0)}</span>
                  </div>
                  <div className="stat-item">
                    <label>总流动性:</label>
                    <span>
                      ${Object.values(tokenData.dexPools)
                        .flat()
                        .reduce((total, pool) => total + (pool.liquidity || 0), 0)
                        .toLocaleString()}
                    </span>
                  </div>
                  <div className="stat-item">
                    <label>24h总交易量:</label>
                    <span>
                      ${Object.values(tokenData.dexPools)
                        .flat()
                        .reduce((total, pool) => total + (pool.volume24h || 0), 0)
                        .toLocaleString()}
                    </span>
                  </div>
                </div>
              </div>
            )}
        </div>
      )}
    </div>
  );
};

export default TokenPriceChecker; 