import React, { useState, useRef } from 'react';
import { Connection, PublicKey, Keypair, SystemProgram, LAMPORTS_PER_SOL, VersionedTransaction, TransactionMessage, SYSVAR_RENT_PUBKEY, TransactionInstruction, Transaction } from '@solana/web3.js';
import { TOKEN_PROGRAM_ID, ASSOCIATED_TOKEN_PROGRAM_ID, getAssociatedTokenAddressSync, createAssociatedTokenAccountIdempotentInstruction } from '@solana/spl-token';
import bs58 from 'bs58';
import './PumpFunLauncher.css';

const PumpFunLauncher = () => {
    // Token information states
    const [tokenInfo, setTokenInfo] = useState({
        name: '',
        symbol: '',
        description: '',
        twitter: '',
        telegram: '',
        website: ''
    });

    // Image upload state
    const [tokenImage, setTokenImage] = useState(null);
    const [imagePreview, setImagePreview] = useState(null);
    const fileInputRef = useRef(null);

    // Wallet and bundling states
    const [bundleWallets, setBundleWallets] = useState([]);
    const [isGeneratingWallets, setIsGeneratingWallets] = useState(false);
    const [bundleSettings, setBundleSettings] = useState({
        numWallets: 1,
        minBuyAmount: 0.001,
        maxBuyAmount: 0.005,
        jitoTip: 0.001,
        delayBetweenTxs: 1000
    });

    // Launch mode states
    const [launchMode, setLaunchMode] = useState('single'); // 'bundle' or 'single'
    const [devBuyAmount, setDevBuyAmount] = useState(0.01); // SOL amount for dev buy

    // Connection and program states
    const [isConnected, setIsConnected] = useState(false);
    const [wallet, setWallet] = useState(null);
    const [connection, setConnection] = useState(null);
    const [isLaunching, setIsLaunching] = useState(false);
    const [launchProgress, setLaunchProgress] = useState([]);

    // RPC endpoints
    const rpcEndpoints = [
        'https://special-necessary-haze.solana-mainnet.quiknode.pro/b0dbc8a9e790ae10f2951cd230bbf4ab9f12851d/',
        'https://api.mainnet-beta.solana.com',
        'https://solana-api.projectserum.com',
        'https://rpc.ankr.com/solana',
        'https://mainnet.helius-rpc.com/?api-key=YOUR_API_KEY'
    ];
    const [selectedRpc, setSelectedRpc] = useState(rpcEndpoints[0]);

    // Pump.Fun program constants
    const PUMP_PROGRAM = new PublicKey("6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P");
    const GLOBAL = new PublicKey("4wTV1YmiEkRvAtNtsSGPtUrqRYQMe5SKy2uB4Jjaxnjf");
    const FEE_RECIPIENT = new PublicKey("CebN5WGQ4jvEPvsVU4EoHEpgzq1VV7AbicfhtW4xC9iM");
    const EVENT_AUTHORITY = new PublicKey("Ce6TQqeHC9p8KetsN6JsjHK7UTZk7nasjjnr7XxXp9F1");
    const MINT_AUTHORITY = new PublicKey("TSLvdd1pWpHVjahSpsvCXUbgwsL3JAcvokwaKt1eokM");
    const MPL_TOKEN_METADATA_PROGRAM_ID = new PublicKey("metaqbxxUerdq28cj1RbAWkYQm3ybzjb6a8bt518x1s");

    // Jito tip accounts
    const JITO_TIP_ACCOUNTS = [
        "96gYZGLnJYVFmbjzopPSU6QiEV5fGqZNyN9nmNhvrZU5",
        "HFqU5x63VTqvQss8hp11i4wVV8bD44PvwucfZ2bU7gRe",
        "Cw8CFyM9FkoMi7K7Crf6HNQqf4uEMzpKw6QNghXLvLkY",
        "ADaUMid9yfUytqMBgopwjb2DTLSokTSzL1zt6iGPaS49",
        "DfXygSm4jCyNCybVYYK6DwvWqjKee8pbDmJGcLWNDXjh",
    ];

    const getRandomTipAccount = () => {
        const randomIndex = Math.floor(Math.random() * JITO_TIP_ACCOUNTS.length);
        return new PublicKey(JITO_TIP_ACCOUNTS[randomIndex]);
    };

    // Connect wallet
    const connectWallet = async () => {
        try {
            const { solana } = window;
            if (solana && solana.isPhantom) {
                const response = await solana.connect();
                const conn = new Connection(selectedRpc, 'confirmed');
                
                // Create a consistent wallet structure
                const walletAdapter = {
                    publicKey: response.publicKey,
                    signTransaction: async (transaction) => {
                        return await solana.signTransaction(transaction);
                    },
                    signAllTransactions: async (transactions) => {
                        return await solana.signAllTransactions(transactions);
                    },
                    isPhantom: true
                };
                
                setWallet(walletAdapter);
                setConnection(conn);
                setIsConnected(true);
                addLog('✅ 钱包连接成功');
            } else {
                alert('请安装Phantom钱包!');
            }
        } catch (error) {
            console.error('钱包连接失败:', error);
            addLog('❌ 钱包连接失败: ' + error.message);
        }
    };

    // Import wallet from private key
    const importWallet = () => {
        const privateKey = prompt('请输入私钥 (Base58格式):');
        if (privateKey) {
            try {
                const keypair = Keypair.fromSecretKey(bs58.decode(privateKey));
                const conn = new Connection(selectedRpc, 'confirmed');
                
                // Create a consistent wallet structure
                const walletAdapter = {
                    publicKey: keypair.publicKey,
                    keypair: keypair,
                    signTransaction: async (transaction) => {
                        transaction.sign([keypair]);
                        return transaction;
                    },
                    signAllTransactions: async (transactions) => {
                        transactions.forEach(tx => tx.sign([keypair]));
                        return transactions;
                    },
                    isPhantom: false
                };
                
                setWallet(walletAdapter);
                setConnection(conn);
                setIsConnected(true);
                addLog('✅ 私钥导入成功');
            } catch (error) {
                console.error('私钥导入失败:', error);
                addLog('❌ 私钥导入失败: ' + error.message);
            }
        }
    };

    // Generate bundle wallets
    const generateBundleWallets = async () => {
        setIsGeneratingWallets(true);
        addLog(`🔄 正在生成 ${bundleSettings.numWallets} 个捆绑钱包...`);
        
        try {
            const wallets = [];
            for (let i = 0; i < bundleSettings.numWallets; i++) {
                const keypair = Keypair.generate();
                const buyAmount = (Math.random() * (bundleSettings.maxBuyAmount - bundleSettings.minBuyAmount) + bundleSettings.minBuyAmount).toFixed(3);
                
                wallets.push({
                    id: i + 1,
                    publicKey: keypair.publicKey.toString(),
                    secretKey: bs58.encode(keypair.secretKey),
                    keypair: keypair,
                    buyAmount: parseFloat(buyAmount),
                    balance: 0
                });
            }
            
            setBundleWallets(wallets);
            addLog(`✅ 成功生成 ${wallets.length} 个捆绑钱包`);
            
            // Check balances
            await checkWalletBalances(wallets);
        } catch (error) {
            console.error('生成钱包失败:', error);
            addLog('❌ 生成钱包失败: ' + error.message);
        } finally {
            setIsGeneratingWallets(false);
        }
    };

    // Check wallet balances
    const checkWalletBalances = async (wallets) => {
        // 确保有连接对象
        let conn = connection;
        if (!conn) {
            addLog('⚠️ 没有连接对象，尝试重新创建连接...');
            try {
                conn = new Connection(selectedRpc, 'confirmed');
                setConnection(conn);
                addLog(`✅ 重新创建连接成功: ${selectedRpc}`);
            } catch (error) {
                addLog('❌ 重新创建连接失败: ' + error.message);
                return;
            }
        }
        
        addLog('🔄 检查钱包余额...');
        addLog(`📡 使用RPC: ${selectedRpc}`);
        const updatedWallets = [];
        let successCount = 0;
        let failCount = 0;
        
        for (let i = 0; i < wallets.length; i++) {
            const wallet = wallets[i];
            try {
                addLog(`🔍 检查钱包 #${wallet.id}: ${wallet.publicKey.slice(0, 8)}...`);
                
                const balance = await conn.getBalance(new PublicKey(wallet.publicKey));
                const balanceSOL = balance / LAMPORTS_PER_SOL;
                
                addLog(`💰 钱包 #${wallet.id} 余额: ${balanceSOL.toFixed(6)} SOL`);
                
                updatedWallets.push({
                    ...wallet,
                    balance: balanceSOL
                });
                successCount++;
                
                // 添加小延迟避免RPC限制
                if (i < wallets.length - 1) {
                    await new Promise(resolve => setTimeout(resolve, 100));
                }
            } catch (error) {
                addLog(`❌ 钱包 #${wallet.id} 余额检查失败: ${error.message}`);
                updatedWallets.push({
                    ...wallet,
                    balance: 0 // 默认设为0
                });
                failCount++;
            }
        }
        
        setBundleWallets(updatedWallets);
        addLog(`✅ 余额检查完成: 成功 ${successCount}，失败 ${failCount}`);
        
        // 显示汇总信息
        const totalBalance = updatedWallets.reduce((sum, w) => sum + w.balance, 0);
        const totalNeeded = updatedWallets.reduce((sum, w) => sum + w.buyAmount, 0);
        addLog(`📊 总余额: ${totalBalance.toFixed(4)} SOL，总需要: ${totalNeeded.toFixed(4)} SOL`);
    };

    // Handle image upload
    const handleImageUpload = (event) => {
        const file = event.target.files[0];
        if (file) {
            if (file.size > 5 * 1024 * 1024) {
                alert('图片大小不能超过5MB');
                return;
            }
            
            setTokenImage(file);
            const reader = new FileReader();
            reader.onload = (e) => setImagePreview(e.target.result);
            reader.readAsDataURL(file);
        }
    };

    // Upload metadata to IPFS
    const uploadMetadata = async () => {
        if (!tokenImage) {
            throw new Error('请选择代币图片');
        }

        addLog('📤 正在上传元数据到IPFS...');
        
        const formData = new FormData();
        formData.append('file', tokenImage);
        formData.append('name', tokenInfo.name);
        formData.append('symbol', tokenInfo.symbol);
        formData.append('description', tokenInfo.description);
        formData.append('twitter', tokenInfo.twitter);
        formData.append('telegram', tokenInfo.telegram);
        formData.append('website', tokenInfo.website);
        formData.append('showName', 'true');

        try {
            const response = await fetch('https://pump.fun/api/ipfs', {
                method: 'POST',
                body: formData,
            });

            if (!response.ok) {
                throw new Error('元数据上传失败');
            }

            const data = await response.json();
            addLog('✅ 元数据上传成功: ' + data.metadataUri);
            return data.metadataUri;
        } catch (error) {
            addLog('❌ 元数据上传失败: ' + error.message);
            throw error;
        }
    };

    // Create token and bundle
    const launchToken = async () => {
        if (!isConnected || !connection || !wallet) {
            alert('请先连接钱包');
            return;
        }

        if (!tokenInfo.name || !tokenInfo.symbol || !tokenImage) {
            alert('请填写完整的代币信息并上传图片');
            return;
        }

        if (launchMode === 'bundle' && bundleWallets.length === 0) {
            alert('请先生成捆绑钱包');
            return;
        }

        setIsLaunching(true);
        setLaunchProgress([]);

        try {
            // Step 1: Upload metadata
            const metadataUri = await uploadMetadata();

            // Step 2: Create mint keypair
            const mintKeypair = Keypair.generate();
            addLog('🔑 生成铸币密钥: ' + mintKeypair.publicKey.toString());

            // Step 3: Create token (包含开发者购买)
            const tokenData = await createToken(mintKeypair, metadataUri);

            // Step 4: Execute bundle trades if in bundle mode
            if (launchMode === 'bundle') {
                await executeBundleTrades(tokenData);
                addLog('🎉 代币发行、开发者购买和捆绑交易完成!');
            } else {
                addLog('🎉 代币发行和开发者购买完成!');
            }
            
            addLog('🪙 代币地址: ' + mintKeypair.publicKey.toString());

        } catch (error) {
            console.error('发行失败:', error);
            addLog('❌ 发行失败: ' + error.message);
        } finally {
            setIsLaunching(false);
        }
    };

    // Create token on Pump.Fun
    const createToken = async (mintKeypair, metadataUri) => {
        addLog('🚀 正在创建代币...');

        try {
            if (!wallet || !wallet.publicKey) {
                throw new Error('钱包未正确连接');
            }

            addLog('📝 准备代币创建参数...');
            
            const owner = wallet.publicKey;
            const mint = mintKeypair;
            
            // Calculate PDAs using the correct method from example
            const [bondingCurve] = PublicKey.findProgramAddressSync(
                [Buffer.from("bonding-curve"), mint.publicKey.toBuffer()],
                PUMP_PROGRAM
            );
            
            // CRITICAL: Use the CORRECT PDA calculation like the example
            const [associatedBondingCurve] = PublicKey.findProgramAddressSync(
                [bondingCurve.toBuffer(), TOKEN_PROGRAM_ID.toBuffer(), mint.publicKey.toBuffer()],
                ASSOCIATED_TOKEN_PROGRAM_ID
            );
            
            const [metadata] = PublicKey.findProgramAddressSync(
                [Buffer.from("metadata"), MPL_TOKEN_METADATA_PROGRAM_ID.toBuffer(), mint.publicKey.toBuffer()],
                MPL_TOKEN_METADATA_PROGRAM_ID
            );

            // Get buyer's associated token account
            const buyerTokenAccount = getAssociatedTokenAddressSync(mint.publicKey, owner);

            addLog('🔧 创建交易指令...');
            
            // Helper functions for buffer encoding
            const bufferFromUInt64 = (value) => {
                let buffer = Buffer.alloc(8);
                buffer.writeBigUInt64LE(BigInt(value)); // eslint-disable-line no-undef
                return buffer;
            };

            const bufferFromString = (value) => {
                const buffer = Buffer.alloc(4 + value.length);
                buffer.writeUInt32LE(value.length, 0);
                buffer.write(value, 4);
                return buffer;
            };

            const transaction = new Transaction();

            // Add compute budget instructions with higher priority
            transaction.add(new TransactionInstruction({
                keys: [],
                programId: new PublicKey("ComputeBudget111111111111111111111111111111"),
                data: Buffer.concat([
                    Buffer.from(Uint8Array.of(2)), // SetComputeUnitLimit
                    bufferFromUInt64(300000) // 300,000 compute units
                ])
            }));
            
            transaction.add(new TransactionInstruction({
                keys: [],
                programId: new PublicKey("ComputeBudget111111111111111111111111111111"),
                data: Buffer.concat([
                    Buffer.from(Uint8Array.of(3)), // SetComputeUnitPrice
                    bufferFromUInt64(200000) // 200,000 microLamports (higher priority)
                ])
            }));

            // Create token instruction - using exact same format as example
            const createData = Buffer.concat([
                Buffer.from("181ec828051c0777", "hex"), // Create instruction discriminator
                bufferFromString(tokenInfo.name),
                bufferFromString(tokenInfo.symbol),
                bufferFromString(metadataUri),
                bufferFromString(owner.toString()),
            ]);

            // Create token instruction - exactly matching the example
            transaction.add(new TransactionInstruction({
                keys: [
                    { pubkey: mint.publicKey, isSigner: true, isWritable: true },
                    { pubkey: MINT_AUTHORITY, isSigner: false, isWritable: false },
                    { pubkey: bondingCurve, isSigner: false, isWritable: true },
                    { pubkey: associatedBondingCurve, isSigner: false, isWritable: true },
                    { pubkey: GLOBAL, isSigner: false, isWritable: false },
                    { pubkey: MPL_TOKEN_METADATA_PROGRAM_ID, isSigner: false, isWritable: false },
                    { pubkey: metadata, isSigner: false, isWritable: true },
                    { pubkey: owner, isSigner: true, isWritable: true },
                    { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
                    { pubkey: TOKEN_PROGRAM_ID, isSigner: false, isWritable: false },
                    { pubkey: ASSOCIATED_TOKEN_PROGRAM_ID, isSigner: false, isWritable: false },
                    { pubkey: SYSVAR_RENT_PUBKEY, isSigner: false, isWritable: false },
                    { pubkey: EVENT_AUTHORITY, isSigner: false, isWritable: false },
                    { pubkey: PUMP_PROGRAM, isSigner: false, isWritable: false }
                ],
                programId: PUMP_PROGRAM,
                data: createData
            }));

            addLog('✅ 代币创建指令已添加');

            // Check and create ATA if needed
            const tokenAccountInfo = await connection.getAccountInfo(buyerTokenAccount);
            if (!tokenAccountInfo) {
                transaction.add(createAssociatedTokenAccountIdempotentInstruction(
                    owner,
                    buyerTokenAccount,
                    owner,
                    mint.publicKey
                ));
                addLog('📝 添加创建ATA指令');
            }

            // Add buy instruction with creator_vault (正确的seeds)
            if (devBuyAmount > 0) {
                addLog('💰 准备开发者购买指令...');
                
                // Calculate creator_vault - 使用错误信息中的期望地址反推seeds
                let creatorVault;
                try {
                    // 尝试不同的seeds组合找到正确的creator_vault
                    const possibleSeeds = [
                        [Buffer.from("creator-vault"), mint.publicKey.toBuffer()],
                        [Buffer.from("creator"), mint.publicKey.toBuffer()], 
                        [owner.toBuffer(), mint.publicKey.toBuffer()],
                        [mint.publicKey.toBuffer(), owner.toBuffer()],
                        [bondingCurve.toBuffer(), Buffer.from("creator")],
                    ];
                    
                    const expectedAddress = "5BPJSg1Ff3C8TVfLV1wopfFBkMMdg2TaJLQvyLymXaDM";
                    let found = false;
                    
                    for (const seeds of possibleSeeds) {
                        try {
                            const [pda] = PublicKey.findProgramAddressSync(seeds, PUMP_PROGRAM);
                            if (pda.toString() === expectedAddress) {
                                creatorVault = pda;
                                addLog(`✅ 找到匹配的creator_vault PDA`);
                                found = true;
                                break;
                            }
                        } catch (e) {
                            continue;
                        }
                    }
                    
                    if (!found) {
                        // 使用硬编码地址作为后备
                        creatorVault = new PublicKey(expectedAddress);
                        addLog(`⚠️ 使用已知的creator_vault地址`);
                    }
                } catch (error) {
                    addLog(`❌ creator_vault计算失败: ${error.message}`);
                    throw error;
                }
                
                // Calculate buy amounts - 修复计算逻辑
                const solInLamports = Math.floor(devBuyAmount * LAMPORTS_PER_SOL);
                addLog(`📊 购买金额: ${devBuyAmount} SOL = ${solInLamports} lamports`);
                
                // 使用更合理的虚拟储备量计算
                const virtualTokenReserves = BigInt(1073000000000000); // eslint-disable-line no-undef
                const virtualSolReserves = BigInt(30000000000); // eslint-disable-line no-undef
                
                // 计算能买到的代币数量 (AMM公式: tokenOut = solIn * tokenReserves / (solReserves + solIn))
                const solInBigInt = BigInt(solInLamports); // eslint-disable-line no-undef
                const tokenOut = (solInBigInt * virtualTokenReserves) / (virtualSolReserves + solInBigInt);
                
                // 25% 滑点保护
                const slippageDecimal = 0.25;
                const maxSolCost = Math.floor(solInLamports * (1 + slippageDecimal));
                
                addLog(`📊 预期获得代币: ${tokenOut.toString()}`);
                addLog(`📊 最大SOL花费: ${maxSolCost / LAMPORTS_PER_SOL} SOL (含滑点)`);

                const buyData = Buffer.concat([
                    bufferFromUInt64("16927863322537952870"), // Buy instruction discriminator
                    bufferFromUInt64(tokenOut.toString()),
                    bufferFromUInt64(maxSolCost.toString()),
                ]);

                // Create和Buy在同一个交易中 - 使用creator_vault
                transaction.add(new TransactionInstruction({
                    keys: [
                        { pubkey: GLOBAL, isSigner: false, isWritable: false },
                        { pubkey: FEE_RECIPIENT, isSigner: false, isWritable: true },
                        { pubkey: mint.publicKey, isSigner: false, isWritable: false },
                        { pubkey: bondingCurve, isSigner: false, isWritable: true },
                        { pubkey: associatedBondingCurve, isSigner: false, isWritable: true },
                        { pubkey: buyerTokenAccount, isSigner: false, isWritable: true },
                        { pubkey: owner, isSigner: true, isWritable: true },
                        { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
                        { pubkey: TOKEN_PROGRAM_ID, isSigner: false, isWritable: false },
                        { pubkey: creatorVault, isSigner: false, isWritable: true }, // 使用creator_vault
                        { pubkey: EVENT_AUTHORITY, isSigner: false, isWritable: false },
                        { pubkey: PUMP_PROGRAM, isSigner: false, isWritable: false },
                    ],
                    programId: PUMP_PROGRAM,
                    data: buyData
                }));

                addLog(`💰 开发者购买指令已添加: ${devBuyAmount} SOL`);
            }

            // Add Jito tip if enabled
            if (bundleSettings.jitoTip > 0) {
                transaction.add(SystemProgram.transfer({
                    fromPubkey: owner,
                    toPubkey: getRandomTipAccount(),
                    lamports: BigInt(bundleSettings.jitoTip * LAMPORTS_PER_SOL), // eslint-disable-line no-undef
                }));
                addLog(`💎 Jito小费已添加: ${bundleSettings.jitoTip} SOL`);
            }

            // Prepare transaction
            transaction.feePayer = owner;
            const { blockhash } = await connection.getLatestBlockhash();
            transaction.recentBlockhash = blockhash;

            // Sign with mint keypair
            transaction.partialSign(mint);

            addLog('🔏 请在钱包中确认交易...');
            addLog(`💰 交易内容: 创建代币 ${devBuyAmount > 0 ? '+ 购买 ' + devBuyAmount + ' SOL' : ''}`);
            
            // Sign with wallet
            const signedTx = await wallet.signTransaction(transaction);

            addLog('📡 发送代币创建交易到区块链...');
            
            let signature;
            try {
                signature = await connection.sendRawTransaction(signedTx.serialize(), {
                    skipPreflight: false, // 启用预检以发现问题
                    preflightCommitment: 'processed',
                    maxRetries: 3
                });
                
                addLog(`📤 交易已发送，签名: ${signature.slice(0, 8)}...`);
            } catch (sendError) {
                addLog(`❌ 发送交易失败: ${sendError.message}`);
                
                // 如果是预检失败，显示更详细的错误信息
                if (sendError.message.includes('Transaction simulation failed')) {
                    addLog('❌ 交易模拟失败，可能的原因:');
                    addLog('  - 账户余额不足');
                    addLog('  - 指令参数错误');
                    addLog('  - 网络拥堵');
                    if (sendError.logs) {
                        addLog('📋 模拟日志:');
                        sendError.logs.forEach((log, index) => {
                            addLog(`  ${index + 1}. ${log}`);
                        });
                    }
                }
                
                throw sendError;
            }

            addLog('⏳ 等待交易确认...');
            addLog(`📋 交易签名: ${signature}`);
            
            try {
                // 使用更长的超时时间和更好的确认策略
                const confirmationResult = await Promise.race([
                    connection.confirmTransaction({
                        signature: signature,
                        blockhash: blockhash,
                        lastValidBlockHeight: (await connection.getBlockHeight()) + 150
                    }, 'confirmed'),
                    new Promise((_, reject) => 
                        setTimeout(() => reject(new Error('确认超时')), 60000) // 60秒超时
                    )
                ]);
                
                if (confirmationResult.value.err) {
                    // 更好的错误处理
                    const errorMsg = JSON.stringify(confirmationResult.value.err);
                    addLog(`❌ 交易确认失败: ${errorMsg}`);
                    throw new Error(`交易失败: ${errorMsg}`);
                } else {
                    addLog('✅ 交易确认成功！');
                }
            } catch (confirmError) {
                addLog(`⚠️ 交易确认超时: ${confirmError.message}`);
                
                // 如果确认超时，尝试获取交易信息
                let transactionSuccess = false;
                try {
                    // 等待一下再检查
                    await new Promise(resolve => setTimeout(resolve, 2000));
                    
                    const txInfo = await connection.getTransaction(signature, {
                        commitment: 'confirmed',
                        maxSupportedTransactionVersion: 0
                    });
                    
                    if (txInfo && !txInfo.meta.err) {
                        addLog('✅ 交易实际上成功了！');
                        transactionSuccess = true;
                    } else if (txInfo && txInfo.meta.err) {
                        addLog(`❌ 交易失败: ${JSON.stringify(txInfo.meta.err)}`);
                        if (txInfo.meta.logMessages) {
                            addLog('📋 交易日志:');
                            txInfo.meta.logMessages.forEach((log, index) => {
                                addLog(`  ${index + 1}. ${log}`);
                            });
                        }
                        throw new Error(`交易失败: ${JSON.stringify(txInfo.meta.err)}`);
                    } else {
                        addLog('❌ 交易不存在或状态未知');
                        throw new Error('交易确认失败，交易可能未执破行');
                    }
                } catch (getTxError) {
                    addLog('❌ 无法获取交易状态，交易很可能失败了');
                    throw new Error(`交易确认失败: ${confirmError.message}`);
                }
                
                if (!transactionSuccess) {
                    throw new Error('交易未成功');
                }
            }

            // 最终确认代币是否真的创建成功
            try {
                addLog('🔍 最终验证代币是否创建成功...');
                const mintInfo = await connection.getTokenSupply(mint.publicKey);
                if (mintInfo && mintInfo.value.amount !== "0") {
                    addLog('✅ 代币创建成功! 代币确实存在于区块链上');
                    addLog(`📊 代币总供应量: ${mintInfo.value.amount}`);
                } else {
                    throw new Error('代币未成功创建或供应量为0');
                }
            } catch (verifyError) {
                addLog(`❌ 代币验证失败: ${verifyError.message}`);
                throw new Error('代币创建失败，区块链上未找到代币');
            }

            addLog('🎉 代币发行完全成功!');
            addLog(`🪙 代币地址: ${mint.publicKey.toString()}`);
            addLog(`🔗 交易链接: https://solscan.io/tx/${signature}`);
            addLog(`🌐 Pump.Fun: https://pump.fun/${mint.publicKey.toString()}`);
            if (devBuyAmount > 0) {
                addLog(`💰 开发者购买: ${devBuyAmount} SOL`);
            }
            if (bundleSettings.jitoTip > 0) {
                addLog(`💎 Jito小费: ${bundleSettings.jitoTip} SOL`);
            }
            
            return {
                mint: mint.publicKey,
                bondingCurve: bondingCurve,
                signature: signature
            };

        } catch (error) {
            addLog('❌ 代币创建失败: ' + error.message);
            console.error('Create token error:', error);
            throw error;
        }
    };

    // Execute bundle trades - 根据原始bundler逻辑重写
    const executeBundleTrades = async (tokenData) => {
        addLog('💰 开始执行捆绑交易...');

        try {
            const { mint, bondingCurve } = tokenData;
            
            // Calculate associated bonding curve using correct method
            const [associatedBondingCurve] = PublicKey.findProgramAddressSync(
                [bondingCurve.toBuffer(), TOKEN_PROGRAM_ID.toBuffer(), mint.toBuffer()],
                ASSOCIATED_TOKEN_PROGRAM_ID
            );

            const { blockhash } = await connection.getLatestBlockhash();
            const bundledTxns = [];

            // Helper functions for data encoding
            const bufferFromUInt64 = (value) => {
                let buffer = Buffer.alloc(8);
                buffer.writeBigUInt64LE(BigInt(value)); // eslint-disable-line no-undef
                return buffer;
            };

            // Process wallets in chunks like original bundler (6 per chunk)
            const chunkSize = 6;
            const chunkedWallets = [];
            for (let i = 0; i < bundleWallets.length; i += chunkSize) {
                chunkedWallets.push(bundleWallets.slice(i, i + chunkSize));
            }

            addLog(`📦 处理 ${chunkedWallets.length} 个钱包块，每块最多 ${chunkSize} 个钱包`);

            // Process each chunk
            for (let chunkIndex = 0; chunkIndex < chunkedWallets.length; chunkIndex++) {
                const chunk = chunkedWallets[chunkIndex];
                const instructions = [];
                const signers = [];

                addLog(`🔄 处理第 ${chunkIndex + 1}/${chunkedWallets.length} 块...`);

                // Create instructions for each wallet in chunk
                for (const walletInfo of chunk) {
                    try {
                        const buyerKeypair = walletInfo.keypair;
                        const buyerAta = getAssociatedTokenAddressSync(mint, buyerKeypair.publicKey);
                        
                        // Create ATA instruction
                        const ataInstruction = createAssociatedTokenAccountIdempotentInstruction(
                            wallet.publicKey, // payer
                            buyerAta,
                            buyerKeypair.publicKey,
                            mint
                        );
                        
                        // 计算购买数量 - 与原始bundler类似的逻辑
                        const solInLamports = Math.floor(walletInfo.buyAmount * LAMPORTS_PER_SOL);
                        const virtualTokenReserves = BigInt(1073000000000000); // eslint-disable-line no-undef
                        const virtualSolReserves = BigInt(30000000000); // eslint-disable-line no-undef
                        const solInBigInt = BigInt(solInLamports); // eslint-disable-line no-undef
                        const tokenOut = (solInBigInt * virtualTokenReserves) / (virtualSolReserves + solInBigInt);
                        const maxSolCost = Math.floor(solInLamports * 1.25); // 25% slippage

                        // Create buy instruction data
                        const buyData = Buffer.concat([
                            bufferFromUInt64("16927863322537952870"), // Buy instruction discriminator
                            bufferFromUInt64(tokenOut.toString()),
                            bufferFromUInt64(maxSolCost.toString()),
                        ]);

                        // Create buy instruction - 需要处理creator_vault
                        let creatorVault;
                        try {
                            // 使用已知的creator_vault地址
                            creatorVault = new PublicKey("5BPJSg1Ff3C8TVfLV1wopfFBkMMdg2TaJLQvyLymXaDM");
                        } catch (error) {
                            addLog(`❌ creator_vault设置失败: ${error.message}`);
                            continue;
                        }

                        const buyInstruction = new TransactionInstruction({
                            keys: [
                                { pubkey: GLOBAL, isSigner: false, isWritable: false },
                                { pubkey: FEE_RECIPIENT, isSigner: false, isWritable: true },
                                { pubkey: mint, isSigner: false, isWritable: false },
                                { pubkey: bondingCurve, isSigner: false, isWritable: true },
                                { pubkey: associatedBondingCurve, isSigner: false, isWritable: true },
                                { pubkey: buyerAta, isSigner: false, isWritable: true },
                                { pubkey: buyerKeypair.publicKey, isSigner: true, isWritable: true },
                                { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
                                { pubkey: TOKEN_PROGRAM_ID, isSigner: false, isWritable: false },
                                { pubkey: creatorVault, isSigner: false, isWritable: true },
                                { pubkey: EVENT_AUTHORITY, isSigner: false, isWritable: false },
                                { pubkey: PUMP_PROGRAM, isSigner: false, isWritable: false },
                            ],
                            programId: PUMP_PROGRAM,
                            data: buyData
                        });

                        instructions.push(ataInstruction, buyInstruction);
                        signers.push(buyerKeypair);

                        addLog(`✅ 钱包 ${buyerKeypair.publicKey.toString().slice(0, 8)}... 购买 ${walletInfo.buyAmount} SOL`);

                    } catch (error) {
                        addLog(`❌ 钱包 ${walletInfo.keypair.publicKey.toString().slice(0, 8)}... 处理失败: ${error.message}`);
                        continue;
                    }
                }

                if (instructions.length === 0) {
                    addLog(`⚠️ 块 ${chunkIndex + 1} 没有有效指令，跳过`);
                    continue;
                }

                // Create versioned transaction like original bundler
                const message = new TransactionMessage({
                    payerKey: wallet.publicKey, // Main wallet pays fees
                    recentBlockhash: blockhash,
                    instructions: instructions,
                }).compileToV0Message();

                const versionedTx = new VersionedTransaction(message);
                
                // Sign with all signers in chunk
                versionedTx.sign([...signers]);

                bundledTxns.push(versionedTx);
                addLog(`📤 块 ${chunkIndex + 1} 交易已创建，包含 ${instructions.length / 2} 个购买操作`);
            }

            // Send all bundle transactions
            addLog(`🚀 发送 ${bundledTxns.length} 个bundler交易...`);
            
            for (let i = 0; i < bundledTxns.length; i++) {
                try {
                    const signature = await connection.sendRawTransaction(bundledTxns[i].serialize(), {
                        skipPreflight: false,
                        preflightCommitment: 'processed',
                        maxRetries: 3
                    });
                    
                    addLog(`📤 Bundle交易 ${i + 1}/${bundledTxns.length} 已发送: ${signature.slice(0, 8)}...`);
                    
                    // 不等待确认，立即发送下一个交易以保持速度
                    
                } catch (error) {
                    addLog(`❌ Bundle交易 ${i + 1} 发送失败: ${error.message}`);
                }
            }

            addLog('✅ 所有bundler交易已发送完成！');

        } catch (error) {
            addLog('❌ Bundle交易执行失败: ' + error.message);
            console.error('Bundle trades error:', error);
            throw error;
        }
    };

    // executeDevBuy函数已被移除 - 开发者购买现在包含在createToken交易中

    // Add log message

    // Execute dev buy as separate transaction
    // executeDevBuy函数已被移除 - 开发者购买现在包含在createToken交易中

    // Add log message
    const addLog = (message) => {
        const timestamp = new Date().toLocaleTimeString();
        setLaunchProgress(prev => [...prev, `[${timestamp}] ${message}`]);
    };

    // Clear logs
    const clearLogs = () => {
        setLaunchProgress([]);
    };

    // 添加交易状态检查功能
    const checkTransactionStatus = async () => {
        const signature = prompt('请输入交易签名:');
        if (!signature) return;

        addLog(`🔍 检查交易状态: ${signature.slice(0, 8)}...`);
        
        try {
            if (!connection) {
                const conn = new Connection(selectedRpc, 'confirmed');
                setConnection(conn);
            }

            // 检查交易状态
            const txInfo = await connection.getTransaction(signature, {
                commitment: 'confirmed',
                maxSupportedTransactionVersion: 0
            });

            if (!txInfo) {
                addLog('❌ 未找到交易，可能还在处理中或交易失败');
                return;
            }

            if (txInfo.meta.err) {
                addLog(`❌ 交易失败: ${JSON.stringify(txInfo.meta.err)}`);
                
                // 尝试解析具体错误
                if (txInfo.meta.logMessages) {
                    addLog('📋 交易日志:');
                    txInfo.meta.logMessages.forEach((log, index) => {
                        addLog(`  ${index + 1}. ${log}`);
                    });
                }
            } else {
                addLog('✅ 交易成功确认!');
                addLog(`💰 交易费用: ${txInfo.meta.fee / LAMPORTS_PER_SOL} SOL`);
                
                // 查找代币铸币地址
                if (txInfo.meta.postTokenBalances && txInfo.meta.postTokenBalances.length > 0) {
                    const tokenInfo = txInfo.meta.postTokenBalances[0];
                    if (tokenInfo.mint) {
                        addLog(`🪙 发现代币: ${tokenInfo.mint}`);
                        
                        // 检查代币信息
                        await checkTokenInfo(tokenInfo.mint);
                    }
                }
            }

            addLog(`🔗 查看交易: https://solscan.io/tx/${signature}`);

        } catch (error) {
            addLog(`❌ 检查交易状态失败: ${error.message}`);
        }
    };

    // 检查代币信息
    const checkTokenInfo = async (mintAddress) => {
        try {
            addLog(`🔍 检查代币信息: ${mintAddress}`);
            
            const mintPublicKey = new PublicKey(mintAddress);
            
            // 获取代币供应量信息
            const mintInfo = await connection.getTokenSupply(mintPublicKey);
            addLog(`📊 代币总供应量: ${mintInfo.value.amount}`);
            addLog(`📊 小数位数: ${mintInfo.value.decimals}`);
            
            // 检查代币账户信息
            const accountInfo = await connection.getAccountInfo(mintPublicKey);
            if (accountInfo) {
                addLog('✅ 代币账户存在');
            } else {
                addLog('❌ 代币账户不存在');
            }

            // 查找 Pump.Fun 上的代币页面
            addLog(`🌐 Pump.Fun 链接: https://pump.fun/${mintAddress}`);
            addLog(`🔗 Solscan 链接: https://solscan.io/token/${mintAddress}`);

        } catch (error) {
            addLog(`❌ 检查代币信息失败: ${error.message}`);
        }
    };

    // 手动检查代币状态
    const checkTokenStatus = async () => {
        const mintAddress = prompt('请输入代币地址:');
        if (!mintAddress) return;

        if (!connection) {
            const conn = new Connection(selectedRpc, 'confirmed');
            setConnection(conn);
        }

        await checkTokenInfo(mintAddress);
    };

    // 预览元数据格式
    const previewMetadata = () => {
        if (!tokenImage) {
            alert('请先选择代币图片');
            return;
        }

        const metadataJson = {
            name: tokenInfo.name,
            symbol: tokenInfo.symbol,
            description: tokenInfo.description,
            image: "[将被替换为图片的IPFS URL]",
            twitter: tokenInfo.twitter || "",
            telegram: tokenInfo.telegram || "",
            website: tokenInfo.website || "",
            showName: "true"
        };

        addLog('📋 将要上传的元数据格式:');
        addLog(JSON.stringify(metadataJson, null, 2));
        addLog('');
        addLog('📝 这个格式与Pump.Fun yuan.json要求完全匹配');
        addLog('🔍 对比实例代码中的格式：');
        addLog('✅ name, symbol, description - 匹配');
        addLog('✅ image - 将自动上传并替换为IPFS URL');
        addLog('✅ twitter, telegram, website - 匹配');
        addLog('✅ showName: "true" - 匹配');
    };

    // 批量转账功能
    const batchTransferToWallets = async () => {
        if (!wallet || !connection) {
            alert('请先连接钱包！');
            return;
        }

        const walletsNeedingFunds = bundleWallets.filter(w => w.balance < w.buyAmount);
        if (walletsNeedingFunds.length === 0) {
            alert('所有钱包余额都充足！');
            return;
        }

        const totalNeeded = walletsNeedingFunds.reduce((sum, w) => sum + (w.buyAmount - w.balance + 0.001), 0);
        
        if (!window.confirm(`需要向 ${walletsNeedingFunds.length} 个钱包转账，总计约 ${totalNeeded.toFixed(4)} SOL。\n确认继续？`)) { // eslint-disable-line no-restricted-globals
            return;
        }

        addLog(`🔄 开始批量转账到 ${walletsNeedingFunds.length} 个钱包...`);

        try {
            let successCount = 0;
            let failCount = 0;

            for (const walletInfo of walletsNeedingFunds) {
                try {
                    const needed = walletInfo.buyAmount - walletInfo.balance + 0.001; // 额外加0.001 SOL作为手续费
                    const lamports = Math.floor(needed * LAMPORTS_PER_SOL);

                    const transaction = new Transaction().add(
                        SystemProgram.transfer({
                            fromPubkey: wallet.publicKey,
                            toPubkey: new PublicKey(walletInfo.publicKey),
                            lamports: lamports,
                        })
                    );

                    const { blockhash } = await connection.getLatestBlockhash();
                    transaction.recentBlockhash = blockhash;
                    transaction.feePayer = wallet.publicKey;

                    const signedTx = await wallet.signTransaction(transaction);
                    const signature = await connection.sendRawTransaction(signedTx.serialize());

                    addLog(`✅ 向钱包#${walletInfo.id} 转账 ${needed.toFixed(4)} SOL: ${signature.slice(0, 8)}...`);
                    successCount++;

                    // 等待确认（可选，会比较慢）
                    // await connection.confirmTransaction(signature, 'confirmed');

                } catch (error) {
                    addLog(`❌ 向钱包#${walletInfo.id} 转账失败: ${error.message}`);
                    failCount++;
                }

                // 短暂延迟避免网络拥堵
                await new Promise(resolve => setTimeout(resolve, 500));
            }

            addLog(`📊 批量转账完成: 成功 ${successCount}，失败 ${failCount}`);
            
            // 刷新余额
            setTimeout(() => {
                checkWalletBalances(bundleWallets);
            }, 3000);

        } catch (error) {
            addLog(`❌ 批量转账失败: ${error.message}`);
        }
    };

    return (
        <div className="pumpfun-launcher">
            <div className="launcher-header">
                <h1>🚀 Pump.Fun 代币发行器</h1>
                <p>创建代币并执行捆绑交易</p>
            </div>

            <div className="launcher-content">
                {/* Wallet Connection */}
                <div className="section">
                    <h3>💳 钱包连接</h3>
                    <div className="wallet-section">
                        <div className="rpc-selector">
                            <label>RPC节点:</label>
                            <select 
                                value={selectedRpc} 
                                onChange={(e) => setSelectedRpc(e.target.value)}
                                disabled={isConnected}
                            >
                                {rpcEndpoints.map((endpoint, index) => (
                                    <option key={index} value={endpoint}>
                                        {endpoint.includes('quiknode') ? 'QuickNode RPC (推荐)' :
                                         endpoint.includes('helius') ? 'Helius RPC' : 
                                         endpoint.includes('ankr') ? 'Ankr RPC' :
                                         endpoint.includes('serum') ? 'Serum RPC' : 'Solana RPC'}
                                    </option>
                                ))}
                            </select>
                        </div>
                        
                        <div className="wallet-buttons">
                            {!isConnected ? (
                                <>
                                    <button onClick={connectWallet} className="connect-btn">
                                        📱 连接 Phantom
                                    </button>
                                    <button onClick={importWallet} className="import-btn">
                                        🔑 导入私钥
                                    </button>
                                </>
                            ) : (
                                <div className="connected-wallet">
                                    <span className="status-indicator">🟢</span>
                                    已连接: {wallet.publicKey.toString().slice(0, 8)}...
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Token Information */}
                <div className="section">
                    <h3>🪙 代币信息</h3>
                    <div className="token-form">
                        <div className="form-row">
                            <div className="form-group">
                                <label>代币名称:</label>
                                <input
                                    type="text"
                                    value={tokenInfo.name}
                                    onChange={(e) => setTokenInfo(prev => ({...prev, name: e.target.value}))}
                                    placeholder="例: My Token"
                                />
                            </div>
                            <div className="form-group">
                                <label>代币符号:</label>
                                <input
                                    type="text"
                                    value={tokenInfo.symbol}
                                    onChange={(e) => setTokenInfo(prev => ({...prev, symbol: e.target.value}))}
                                    placeholder="例: MTK"
                                />
                            </div>
                        </div>

                        <div className="form-group">
                            <label>代币描述:</label>
                            <textarea
                                value={tokenInfo.description}
                                onChange={(e) => setTokenInfo(prev => ({...prev, description: e.target.value}))}
                                placeholder="描述你的代币..."
                                rows="3"
                            />
                        </div>

                        <div className="form-row">
                            <div className="form-group">
                                <label>Twitter:</label>
                                <input
                                    type="text"
                                    value={tokenInfo.twitter}
                                    onChange={(e) => setTokenInfo(prev => ({...prev, twitter: e.target.value}))}
                                    placeholder="https://twitter.com/..."
                                />
                            </div>
                            <div className="form-group">
                                <label>Telegram:</label>
                                <input
                                    type="text"
                                    value={tokenInfo.telegram}
                                    onChange={(e) => setTokenInfo(prev => ({...prev, telegram: e.target.value}))}
                                    placeholder="https://t.me/..."
                                />
                            </div>
                        </div>

                        <div className="form-group">
                            <label>网站:</label>
                            <input
                                type="text"
                                value={tokenInfo.website}
                                onChange={(e) => setTokenInfo(prev => ({...prev, website: e.target.value}))}
                                placeholder="https://..."
                            />
                        </div>

                        {/* Image Upload */}
                        <div className="form-group">
                            <label>代币图片:</label>
                            <div className="image-upload">
                                <input
                                    type="file"
                                    ref={fileInputRef}
                                    onChange={handleImageUpload}
                                    accept="image/*"
                                    style={{ display: 'none' }}
                                />
                                <button onClick={() => fileInputRef.current?.click()} className="upload-btn">
                                    📷 选择图片
                                </button>
                                {imagePreview && (
                                    <div className="image-preview">
                                        <img src={imagePreview} alt="Token preview" />
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>

                {/* Launch Mode Selection */}
                <div className="section">
                    <h3>🎯 发行模式</h3>
                    <div className="launch-mode-selector">
                        <div className="mode-options">
                            <label className={`mode-option ${launchMode === 'single' ? 'selected' : ''}`}>
                                <input
                                    type="radio"
                                    value="single"
                                    checked={launchMode === 'single'}
                                    onChange={(e) => setLaunchMode(e.target.value)}
                                />
                                <div className="mode-content">
                                    <div className="mode-icon">💎</div>
                                    <div className="mode-title">不捆绑买入</div>
                                    <div className="mode-desc">只发行代币，开发者购买指定数量，不进行捆绑交易</div>
                                </div>
                            </label>
                            
                            <label className={`mode-option ${launchMode === 'bundle' ? 'selected' : ''}`}>
                                <input
                                    type="radio"
                                    value="bundle"
                                    checked={launchMode === 'bundle'}
                                    onChange={(e) => setLaunchMode(e.target.value)}
                                />
                                <div className="mode-content">
                                    <div className="mode-icon">📦</div>
                                    <div className="mode-title">捆绑买入</div>
                                    <div className="mode-desc">发行代币，开发者购买+多钱包捆绑交易</div>
                                </div>
                            </label>
                        </div>
                        
                        <div className="dev-buy-settings">
                            <div className="form-group">
                                <label>开发者购买数量 (SOL):</label>
                                <input
                                    type="number"
                                    step="0.01"
                                    value={devBuyAmount}
                                    onChange={(e) => setDevBuyAmount(e.target.value === '' ? '' : parseFloat(e.target.value) || 0)}
                                    min="0.01"
                                    placeholder="开发者购买的SOL数量"
                                />
                            </div>
                            <div className="buy-info">
                                <p>💡 {launchMode === 'single' ? 
                                    '不捆绑模式：只进行开发者购买，不执行多钱包捆绑交易' :
                                    '捆绑模式：先进行开发者购买，然后执行多钱包捆绑交易'
                                }</p>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Bundle Settings */}
                {launchMode === 'bundle' && (
                    <div className="section">
                        <h3>📦 捆绑设置</h3>
                    <div className="bundle-settings">
                        <div className="form-row">
                            <div className="form-group">
                                <label>钱包数量:</label>
                                                            <input
                                type="number"
                                value={bundleSettings.numWallets}
                                onChange={(e) => setBundleSettings(prev => ({...prev, numWallets: e.target.value === '' ? '' : parseInt(e.target.value) || 0}))}
                                min="1"
                                max="50"
                            />
                            </div>
                            <div className="form-group">
                                <label>Jito 小费 (SOL):</label>
                                <input
                                    type="number"
                                    step="0.001"
                                    value={bundleSettings.jitoTip}
                                    onChange={(e) => setBundleSettings(prev => ({...prev, jitoTip: e.target.value === '' ? '' : parseFloat(e.target.value) || 0}))}
                                />
                            </div>
                        </div>

                        <div className="form-row">
                            <div className="form-group">
                                <label>最小购买量 (SOL):</label>
                                <input
                                    type="number"
                                    step="0.01"
                                    value={bundleSettings.minBuyAmount}
                                    onChange={(e) => setBundleSettings(prev => ({...prev, minBuyAmount: e.target.value === '' ? '' : parseFloat(e.target.value) || 0}))}
                                />
                            </div>
                            <div className="form-group">
                                <label>最大购买量 (SOL):</label>
                                <input
                                    type="number"
                                    step="0.01"
                                    value={bundleSettings.maxBuyAmount}
                                    onChange={(e) => setBundleSettings(prev => ({...prev, maxBuyAmount: e.target.value === '' ? '' : parseFloat(e.target.value) || 0}))}
                                />
                            </div>
                        </div>

                        <div className="form-group">
                            <label>交易间隔 (毫秒):</label>
                            <input
                                type="number"
                                value={bundleSettings.delayBetweenTxs}
                                onChange={(e) => setBundleSettings(prev => ({...prev, delayBetweenTxs: e.target.value === '' ? '' : parseInt(e.target.value) || 0}))}
                                min="100"
                            />
                        </div>

                        <div className="bundle-actions">
                            <button 
                                onClick={generateBundleWallets}
                                disabled={isGeneratingWallets}
                                className="generate-btn"
                            >
                                {isGeneratingWallets ? '🔄 生成中...' : '🎲 生成捆绑钱包'}
                            </button>
                            
                            {bundleWallets.length > 0 && (
                                <button 
                                    onClick={() => checkWalletBalances(bundleWallets)}
                                    className="refresh-btn"
                                >
                                    🔄 刷新余额
                                </button>
                            )}
                        </div>
                    </div>
                </div>)}

                {/* Bundle Wallets Display */}
                {launchMode === 'bundle' && bundleWallets.length > 0 && (
                    <div className="section">
                        <h3>👛 捆绑钱包 ({bundleWallets.length})</h3>
                        
                        {/* Wallet Management Tools */}
                        <div className="wallet-tools">
                            <button 
                                onClick={() => {
                                    const addresses = bundleWallets.map(w => w.publicKey).join('\n');
                                    navigator.clipboard.writeText(addresses);
                                    alert('所有钱包地址已复制到剪贴板！');
                                }}
                                className="tool-btn"
                            >
                                📋 复制所有地址
                            </button>
                            
                            <button 
                                onClick={() => {
                                    const keys = bundleWallets.map(w => w.secretKey).join('\n');
                                    navigator.clipboard.writeText(keys);
                                    alert('所有私钥已复制到剪贴板！');
                                }}
                                className="tool-btn"
                            >
                                🔑 复制所有私钥
                            </button>
                            
                            <button 
                                onClick={() => {
                                    const data = bundleWallets.map(w => 
                                        `钱包#${w.id}: ${w.publicKey} | 购买: ${w.buyAmount} SOL | 余额: ${w.balance.toFixed(4)} SOL`
                                    ).join('\n');
                                    navigator.clipboard.writeText(data);
                                    alert('完整钱包信息已复制到剪贴板！');
                                }}
                                className="tool-btn"
                            >
                                📊 导出钱包信息
                            </button>
                            
                            <button 
                                onClick={() => {
                                    const totalNeeded = bundleWallets.reduce((sum, w) => sum + w.buyAmount, 0);
                                    const totalBalance = bundleWallets.reduce((sum, w) => sum + w.balance, 0);
                                    alert(`总需要: ${totalNeeded.toFixed(4)} SOL\n当前余额: ${totalBalance.toFixed(4)} SOL\n缺少: ${Math.max(0, totalNeeded - totalBalance).toFixed(4)} SOL`);
                                }}
                                className="tool-btn"
                            >
                                💰 余额统计
                            </button>
                            
                            <button 
                                onClick={() => {
                                    // 生成批量转账指令
                                    const commands = bundleWallets
                                        .filter(w => w.balance < w.buyAmount)
                                        .map(w => {
                                            const needed = (w.buyAmount - w.balance + 0.001).toFixed(4); // 多加一点手续费
                                            return `solana transfer ${w.publicKey} ${needed} --from YOUR_WALLET_PATH`;
                                        });
                                    
                                    if (commands.length === 0) {
                                        alert('所有钱包余额都充足！');
                                        return;
                                    }
                                    
                                    const script = `#!/bin/bash\n# Bundle钱包批量转账脚本\n# 请先安装Solana CLI并设置好钱包\n\n${commands.join('\n')}\n\necho "批量转账完成!"`;
                                    navigator.clipboard.writeText(script);
                                    alert(`已生成 ${commands.length} 个转账指令并复制到剪贴板！\n请在终端中执行或保存为脚本文件。`);
                                }}
                                className="tool-btn"
                            >
                                🔄 生成转账脚本
                            </button>
                            
                            <button 
                                onClick={batchTransferToWallets}
                                className="tool-btn transfer-btn"
                                disabled={!isConnected}
                            >
                                💸 批量转账
                            </button>
                        </div>

                        {/* Wallets List */}
                        <div className="wallets-container">
                            <div className="wallets-list">
                                {bundleWallets.map((wallet) => (
                                    <div key={wallet.id} className="wallet-item">
                                        <div className="wallet-header">
                                            <span className="wallet-id">钱包 #{wallet.id}</span>
                                            <span className={`balance-status ${wallet.balance >= wallet.buyAmount ? 'sufficient' : 'insufficient'}`}>
                                                {wallet.balance >= wallet.buyAmount ? '✅' : '⚠️'}
                                            </span>
                                        </div>
                                        
                                        <div className="wallet-address-row">
                                            <span className="label">地址:</span>
                                            <div className="address-container">
                                                <span className="address">{wallet.publicKey}</span>
                                                <button 
                                                    onClick={() => {
                                                        navigator.clipboard.writeText(wallet.publicKey);
                                                        alert(`钱包#${wallet.id}地址已复制！`);
                                                    }}
                                                    className="copy-btn"
                                                    title="复制地址"
                                                >
                                                    📋
                                                </button>
                                            </div>
                                        </div>
                                        
                                        <div className="wallet-details">
                                            <div className="detail-item">
                                                <span className="label">购买:</span>
                                                <span className="value">{wallet.buyAmount} SOL</span>
                                            </div>
                                            <div className="detail-item">
                                                <span className="label">余额:</span>
                                                <span className={`value ${wallet.balance >= wallet.buyAmount ? 'sufficient' : 'insufficient'}`}>
                                                    {wallet.balance.toFixed(4)} SOL
                                                </span>
                                            </div>
                                            <div className="detail-item">
                                                <span className="label">需要:</span>
                                                <span className="value">
                                                    {Math.max(0, wallet.buyAmount - wallet.balance).toFixed(4)} SOL
                                                </span>
                                            </div>
                                        </div>
                                        
                                        <div className="wallet-actions">
                                            <button 
                                                onClick={() => {
                                                    navigator.clipboard.writeText(wallet.secretKey);
                                                    alert(`钱包#${wallet.id}私钥已复制！`);
                                                }}
                                                className="action-btn"
                                            >
                                                🔑 复制私钥
                                            </button>
                                            <a 
                                                href={`https://solscan.io/account/${wallet.publicKey}`}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="action-btn"
                                            >
                                                🔗 Solscan
                                            </a>
                                        </div>
                                    </div>
                                ))}
                            </div>
                            
                            {/* Summary */}
                            <div className="wallets-summary">
                                <div className="summary-item">
                                    <span className="label">总钱包数:</span>
                                    <span className="value">{bundleWallets.length}</span>
                                </div>
                                <div className="summary-item">
                                    <span className="label">总需要 SOL:</span>
                                    <span className="value">{bundleWallets.reduce((sum, w) => sum + w.buyAmount, 0).toFixed(4)}</span>
                                </div>
                                <div className="summary-item">
                                    <span className="label">当前总余额:</span>
                                    <span className="value">{bundleWallets.reduce((sum, w) => sum + w.balance, 0).toFixed(4)}</span>
                                </div>
                                <div className="summary-item">
                                    <span className="label">余额充足钱包:</span>
                                    <span className="value">
                                        {bundleWallets.filter(w => w.balance >= w.buyAmount).length}/{bundleWallets.length}
                                    </span>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* Launch Button */}
                <div className="section">
                    <div className="launch-section">
                        <button
                            onClick={launchToken}
                            disabled={!isConnected || isLaunching || !tokenInfo.name || !tokenInfo.symbol || (launchMode === 'bundle' && bundleWallets.length === 0)}
                            className="launch-btn"
                        >
                            {isLaunching ? '🚀 发行中...' : 
                             launchMode === 'single' ? '🚀 发行代币(不捆绑)' : 
                             '🚀 发行代币(捆绑买入)'}
                        </button>
                        
                        <div className="launch-warning">
                            {launchMode === 'bundle' ? 
                                '⚠️ 请确保开发者钱包和所有捆绑钱包都有足够的SOL余额' :
                                '⚠️ 请确保开发者钱包有足够的SOL余额进行购买'
                            }
                        </div>
                    </div>
                </div>

                {/* Progress Logs */}
                {launchProgress.length > 0 && (
                    <div className="section">
                        <div className="logs-header">
                            <h3>📊 执行日志</h3>
                            <div className="logs-actions">
                                <button onClick={clearLogs} className="clear-logs-btn">
                                    🗑️ 清除日志
                                </button>
                                <button onClick={checkTransactionStatus} className="check-btn">
                                    🔍 检查交易
                                </button>
                                <button onClick={checkTokenStatus} className="check-btn">
                                    🪙 检查代币
                                </button>
                                <button onClick={previewMetadata} className="preview-btn">
                                    📋 预览元数据
                                </button>
                            </div>
                        </div>
                        <div className="progress-logs">
                            {launchProgress.map((log, index) => (
                                <div key={index} className="log-entry">
                                    {log}
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default PumpFunLauncher; 